const crypto = require('crypto');

const headers = $input.first().json.headers;
const slackSignature = headers['x-slack-signature'];

if (slackSignature) {
  // ── Slack signing verification ──
  const binData = await this.helpers.getBinaryDataBuffer(0, 'data');
  const rawBody = await this.helpers.binaryToString(binData);

  const signingSecret = $env.SLACK_SIGNING_SECRET;
  const timestamp = headers['x-slack-request-timestamp'];

  if (Math.abs(Math.floor(Date.now() / 1000) - parseInt(timestamp)) > 300) {
    throw new Error('Request too old');
  }

  const sigBasestring = `v0:${timestamp}:${rawBody}`;
  const computed = 'v0=' + crypto
    .createHmac('sha256', signingSecret)
    .update(sigBasestring, 'utf8')
    .digest('hex');

  if (!crypto.timingSafeEqual(Buffer.from(computed), Buffer.from(slackSignature))) {
    throw new Error('Invalid Slack signature');
  }
} else {
  // ── API key verification (for Claude Code) ──
  const authHeader = headers['authorization'] || '';
  const expectedKey = $env.CLAUDE_CODE_N8N_API_KEY;

  if (!expectedKey || authHeader !== `Bearer ${expectedKey}`) {
    throw new Error('Unauthorized: invalid or missing API key');
  }
}

return $input.all();

const input = $input.first().json;
const headers = input.headers;
const body = input.body;
const isSlack = !!headers['x-slack-signature'];

let rawText, userName, responseUrl;

if (isSlack) {
  rawText = (body.text || '').trim();
  userName = body.user_name || 'unknown';
  responseUrl = body.response_url || '';
} else {
  rawText = (body.text || '').trim();
  userName = body.user || 'claude-code';
  responseUrl = '';
}

// Parse status and task from text
const validStatuses = ['STARTED', 'PAUSED', 'RESUMED'];
const parts = rawText.split(/\s+/);
const firstWord = (parts[0] || '').toUpperCase();
const isValidStatus = validStatuses.includes(firstWord);

const status = isValidStatus ? firstWord : '';
const task = isValidStatus ? parts.slice(1).join(' ') : rawText;

const now = new Date();
const timestamp = now.toISOString();

return [{
  json: {
    isValidStatus,
    isSlack,
    status,
    task,
    rawText,
    userName,
    responseUrl,
    timestamp,
  }
}];

// Post confirmation to Slack only if this came from a Slack slash command
const responseUrl = $('Validate & Extract').item.json.responseUrl;
const status = $('Validate & Extract').item.json.status;
const task = $('Validate & Extract').item.json.task;

if (responseUrl) {
  const taskSuffix = task ? ` ${task}` : '';
  await this.helpers.httpRequest({
    method: 'POST',
    url: responseUrl,
    body: {
      response_type: 'ephemeral',
      text: `\u2705 Logged: *${status}*${taskSuffix}`,
    },
    json: true,
  });
}

return [{ json: { success: true } }];

// Post error to Slack only if this came from a Slack slash command
const responseUrl = $('Validate & Extract').item.json.responseUrl;
const rawText = $('Validate & Extract').item.json.rawText;

if (responseUrl) {
  const hint = rawText
    ? `\u274c Invalid status: "${rawText}".\nUsage: \`/log STARTED\`, \`/log PAUSED\`, or \`/log RESUMED\``
    : `\u274c Please provide a status.\nUsage: \`/log STARTED\`, \`/log PAUSED\`, or \`/log RESUMED\``;

  await this.helpers.httpRequest({
    method: 'POST',
    url: responseUrl,
    body: {
      response_type: 'ephemeral',
      text: hint,
    },
    json: true,
  });
}

return [{ json: { success: false } }];
